inputs = ['fwff', 'cfb', 'fzd', 'jh', 'byeg']
outputs = ['bwbb', 'cbb', 'bjd', 'jh', 'bawzdeg']

print("Detailed analysis of each transformation:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")
    # Let's see what single character changes occur
    min_len = min(len(inp), len(outp))
    changes = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            changes.append((j, inp[j], outp[j]))
    if len(inp) != len(outp):
        if len(inp) > len(outp):
            print(f"  Removed characters at positions {list(range(len(outp), len(inp)))}")
        else:
            print(f"  Added characters at positions {list(range(len(inp), len(outp)))}")
    if changes:
        for pos, from_char, to_char in changes:
            print(f"  Position {pos}: '{from_char}' -> '{to_char}'")
    print()

# The issue is definitely with the last case: 'byeg' -> 'bawzdeg'
# This requires adding characters at the end, which str.replace() cannot do.

